import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from sklearn.preprocessing import StandardScaler

MAX_DRIVERS = 5

def design(feats):
    # Identify strongest features by mean difference
    means = [np.mean(feats.x[feats.y == 1, feats.column(fid)]) 
             - np.mean(feats.x[feats.y == 0, feats.column(fid)]) 
             for fid in feats.ids]

    # Sort by absolute mean difference
    sorted_idx = np.argsort(np.abs(means))[::-1]
    top_features = [feats.ids[i] for i in sorted_idx[:20]]

    # Remove near-duplicates based on correlation
    to_remove = set()
    corr_matrix = np.corrcoef(feats.x[:, [feats.column(fid) for fid in top_features]].T)
    for i in range(len(top_features)):
        for j in range(i+1, len(top_features)):
            if abs(corr_matrix[i,j]) >= 0.6:
                to_remove.add(top_features[j])

    filtered_features = [fid for fid in top_features if fid not in to_remove]

    # Check for interaction terms among top features
    best_product = None
    best_p = 1.0

    for i, fid1 in enumerate(filtered_features[:10]):
        for j, fid2 in enumerate(filtered_features[i+1:10]):
            # Compute product feature
            col1 = feats.column(fid1)
            col2 = feats.column(fid2)
            prod_vals = feats.x[:, col1] * feats.x[:, col2]

            # Test association with outcome using t-test
            y0 = prod_vals[feats.y == 0]
            y1 = prod_vals[feats.y == 1]
            t_stat, p_val = stats.ttest_ind(y1, y0, equal_var=False)

            if p_val < best_p and p_val < 0.05:
                best_p = p_val
                best_product = (fid1, fid2)

    if best_product:
        return Design(
            drivers=(best_product[0],),
            columns=(best_product[0], best_product[1]),
            products=(best_product,),
            loadings={best_product[0]: 1.0}
        )

    # If no strong interaction, return top single feature
    if filtered_features:
        return Design(
            drivers=(filtered_features[0],),
            columns=(filtered_features[0],),
            products=(),
            loadings={filtered_features[0]: 1.0}
        )

    return Design(drivers=(), columns=(), products=(), loadings={})

